cat > /tmp/gaps.mjs <<'EOF'
import fs from 'fs';
const calls=JSON.parse(fs.readFileSync('/tmp/calls.json','utf8'));
const progs={}; const asAny={}; const trunc=[]; const retries=[]; const execShell=[];
for (const c of calls){ const code=c.code;
 for (const m of code.matchAll(/execFile\(\s*"([\w.-]+)"\s*,\s*\[\s*"([\w-]+)"(?:\s*,\s*"([\w-]+)")?/g)) { const k=m[1]+' '+m[2]+(m[1]==='gh'&&m[3]?' '+m[3]:''); progs[k]=(progs[k]||0)+1; }
 for (const m of code.matchAll(/const (\w+) = \(\.\.\.a: string\[\]\) => execFile\("(\w+)"/g)) { const re=new RegExp(m[1]+'\\(\\s*"([\\w-]+)"','g'); for (const x of code.matchAll(re)) { const k=m[2]+' '+x[1]+' (helper)'; progs[k]=(progs[k]||0)+1; } }
 for (const m of code.matchAll(/run\(\["([\w-]+)"/g)) { const k='git? '+m[1]+' (run helper)'; progs[k]=(progs[k]||0)+1; }
 for (const m of code.matchAll(/(\w+)\(([^()]|\([^()]*\))*\bas any\)/g)) asAny[m[1]]=(asAny[m[1]]||0)+1;
 if (/exec\(/.test(code) && c.fns.includes('shell.exec')) execShell.push(`[${c.thread}#${c.i}] ${(code.match(/exec\(\s*[`"']([^`"']{0,120})/)||[])[1]}`);
 if (/omitted|truncated": true|\[truncated/.test(c.res||'')) trunc.push(`[${c.thread}#${c.i}] ${c.label} fns=${c.fns.filter(f=>!f.startsWith('pit.')&&!f.startsWith('p.')).join(',')} :: ${(c.res.match(/.{0,80}(omitted|truncated": true).{0,60}/)||[''])[0].replace(/\s+/g,' ')}`);
}
for (let i=1;i<calls.length;i++){ const a=calls[i-1], b=calls[i]; if(a.thread===b.thread && !a.isError){ const fa=a.fns.filter(f=>!/^(pit|p)\./.test(f)).sort().join(), fb=b.fns.filter(f=>!/^(pit|p)\./.test(f)).sort().join(); if(fa && fa===fb && /wait|validate|runTargeted|commit|format|completedCalls|verify/.test(fa)) retries.push(`[${b.thread}#${b.i}] after ok ${a.label} -> ${b.label} (${fb}) :: prev result ${String(a.res).replace(/\s+/g,' ').slice(0,200)}`);} }
console.log(JSON.stringify({progs:Object.entries(progs).sort((a,b)=>b[1]-a[1]), asAny},null,0));
console.log('SHELL.EXEC'); execShell.forEach(x=>console.log(x));
console.log('TRUNC'); trunc.forEach(x=>console.log(x));
console.log('REPEATS'); retries.forEach(x=>console.log(x));
EOF
node /tmp/gaps.mjs
